css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .pi-fila{display: grid; grid-template-columns: repeat(2, 1fr); gap: 7px 30px;}
.mz .pi-item{display: flex; align-items: center; gap: 10px; font-size: 17px; font-weight: 700;}
.mz .pi-item .nn{min-width: 52px;}
.mz .pi-item .caja-resp{flex: 1; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .sig-fila{display: flex; align-items: center; gap: 9px; font-size: 16px; font-weight: 700; margin-bottom: 7px; flex-wrap: wrap;}
.mz .sig-fila .nn{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 12px; background: #f3f3f3;}
.mz .sig-fila .caja-sig{width: 66px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .sig-fila .txt{font-size: 13.5px; font-weight: 600;}
.mz .serie-cajas{display: flex; gap: 6px; flex-wrap: wrap; font-size: 16px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 52px; height: 42px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .serie-label{font-size: 12.5px; font-weight: 600; font-family: sans-serif; margin-bottom: 4px;}
.mz .rodea-fila{display: flex; gap: 14px; flex-wrap: wrap;}
.mz .rodea-grupo{display: flex; gap: 12px; font-size: 18px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 10px; padding: 7px 15px;}
